/// The top-level `todo` of a decision's push (category TODO_DECIDE, or TODO_DECIDE_OPEN, which no app gives actions;
/// docs/assistant/todos.md "Waiting for the owner") and of its WebSocket notify: what its Take Recommendation needs,
/// and from a manager that says how the push may answer it (#10465) the ask, the lock-screen rule and the options. A
/// push from an older manager carries the first four only and keeps TODO_DECIDE. The cases are in
/// spec/fixtures/todo-push.
public nonisolated struct TodoDecidePush: Codable, Hashable, Sendable {
    /// The to-do.
    public var id: TodoID
    /// The round the decision waits in, as POST /api/v1/todos/{id}/accept takes it: an answer to an earlier round
    /// takes nothing.
    public var askedAt: String
    /// The label of the recommended option, which Take Recommendation takes.
    public var recommend: String
    /// The manager whose to-do it is, which every answer names in X-Persona-Manager.
    public var manager: String?
    /// The decision's ask in the to-do's view (OwnerAsk.id), which an answer from the notification names; absent from
    /// an older manager.
    public var ask: String?
    /// What the notification may offer: answer, the category stays TODO_DECIDE and the options may be its actions;
    /// open_only, the category is TODO_DECIDE_OPEN, with no action, and a tap opens the app. Absent from an older
    /// manager: Take Recommendation only, as before.
    public var lockscreen: String?
    /// The decision's option labels, whole, the recommended first; only with lockscreen answer, and with
    /// aps.mutable-content so the app's notification service extension can offer them. The hub drops both rather than
    /// cut the alert under 500 characters when the push would not fit otherwise, never the category, lockscreen or
    /// ask.
    public var options: [String]?

    public init(id: TodoID = TodoID(""), askedAt: String = "", recommend: String = "", manager: String? = nil, ask: String? = nil, lockscreen: String? = nil, options: [String]? = nil) {
        self.id = id
        self.askedAt = askedAt
        self.recommend = recommend
        self.manager = manager
        self.ask = ask
        self.lockscreen = lockscreen
        self.options = options
    }

    enum CodingKeys: String, CodingKey {
        case id
        case askedAt = "asked_at"
        case recommend
        case manager
        case ask
        case lockscreen
        case options
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.id = (try? c.decodeIfPresent(TodoID.self, forKey: .id)) ?? TodoID("")
        self.askedAt = (try? c.decodeIfPresent(String.self, forKey: .askedAt)) ?? ""
        self.recommend = (try? c.decodeIfPresent(String.self, forKey: .recommend)) ?? ""
        self.manager = try? c.decodeIfPresent(String.self, forKey: .manager)
        self.ask = try? c.decodeIfPresent(String.self, forKey: .ask)
        self.lockscreen = try? c.decodeIfPresent(String.self, forKey: .lockscreen)
        self.options = try? c.decodeIfPresent([String].self, forKey: .options)
    }
}

/// What came of an answer to one of a to-do's asks (TodoAskAnswered): answered, the answer was taken (an option, a
/// fixed answer, the owner's words, a failed start started again, a conclusion acknowledged), though the ask may
/// still wait (explain_first leaves it waiting while the supervisor explains), so a client draws the reply's todo
/// rather than dropping the ask; declined, Don't handle was kept, with a receipt that undoes it; later, nothing was
/// written and the ask still waits (the client keeps Later for its app session); undone, a Don't handle was undone
/// and the ask waits again. Open: a newer hub may send other values.
public nonisolated enum TodoAskOutcome {
    public static let answered = "answered"
    public static let declined = "declined"
    public static let later = "later"
    public static let undone = "undone"
    public static let all = ["answered", "declined", "later", "undone"]
}

/// An answer that is an outcome rather than an option, a fixed answer or words (TodoAskAnswer.outcome): later, not
/// now: nothing is written; decline, Don't handle a decision, kept with a receipt; undo, that Don't handle undone,
/// with its receipt.
public nonisolated enum TodoAskAnswerOutcome {
    public static let later = "later"
    public static let decline = "decline"
    public static let undo = "undo"
    public static let all = ["later", "decline", "undo"]
}

/// The body of POST /api/v1/todos/{id}/asks/{ask}/answer (#10465), the answer to one of the to-do's own asks, named
/// by its view's ask id: at most one of option, response, text and outcome. None is the ask's one action: a failed
/// start started again, a conclusion that says the work cannot be done acknowledged. A run's ask is answered at its
/// card, not here. The operation's id is the X-Persona-Op-Id header, never the body.
public nonisolated struct TodoAskAnswer: Codable, Hashable, Sendable {
    /// The label of one of a decision's options, as its ask lists it; the recommended one takes the recommendation.
    public var option: String?
    /// A fixed answer to a decision that says the owner cannot answer it as asked: nothing is taken, and the to-do's
    /// supervisor is told.
    public var response: String?
    /// The owner's own words answering a decision, at most 4000 characters (400 beyond): sent to the to-do's Agent as
    /// they are, and kept with its decisions.
    public var text: String?
    public var outcome: String?
    /// With outcome undo: the receipt the decline answered.
    public var receipt: String?

    public init(option: String? = nil, response: String? = nil, text: String? = nil, outcome: String? = nil, receipt: String? = nil) {
        self.option = option
        self.response = response
        self.text = text
        self.outcome = outcome
        self.receipt = receipt
    }

    enum CodingKeys: String, CodingKey {
        case option
        case response
        case text
        case outcome
        case receipt
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.option = try? c.decodeIfPresent(String.self, forKey: .option)
        self.response = try? c.decodeIfPresent(String.self, forKey: .response)
        self.text = try? c.decodeIfPresent(String.self, forKey: .text)
        self.outcome = try? c.decodeIfPresent(String.self, forKey: .outcome)
        self.receipt = try? c.decodeIfPresent(String.self, forKey: .receipt)
    }
}

/// The answer of POST /api/v1/todos/{id}/asks/{ask}/answer (#10465): what came of the answer, and the to-do as it
/// reads after it, so a client sets its row from one answer.
public nonisolated struct TodoAskAnswered: Codable, Hashable, Sendable {
    /// The ask answered, as the path named it.
    public var ask: String
    public var outcome: String
    /// none: no Agent could receive the answer, which is recorded and handed to the to-do's supervisor to pass on.
    /// Absent when it reached the Agent or nothing had to be sent.
    public var delivered: String?
    /// With outcome declined: the receipt outcome undo takes.
    public var receipt: String?
    /// The to-do's row with its view, as GET /api/v1/todos/{id} answers it under todo (for a step's ask, the to-do
    /// whose row lists it), read after the answer: it says whether the ask still waits, whatever the outcome; absent
    /// when it could not be read.
    public var todo: JSONValue?

    public init(ask: String = "", outcome: String = "", delivered: String? = nil, receipt: String? = nil, todo: JSONValue? = nil) {
        self.ask = ask
        self.outcome = outcome
        self.delivered = delivered
        self.receipt = receipt
        self.todo = todo
    }

    enum CodingKeys: String, CodingKey {
        case ask
        case outcome
        case delivered
        case receipt
        case todo
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.ask = (try? c.decodeIfPresent(String.self, forKey: .ask)) ?? ""
        self.outcome = (try? c.decodeIfPresent(String.self, forKey: .outcome)) ?? ""
        self.delivered = try? c.decodeIfPresent(String.self, forKey: .delivered)
        self.receipt = try? c.decodeIfPresent(String.self, forKey: .receipt)
        self.todo = try? c.decodeIfPresent(JSONValue.self, forKey: .todo)
    }
}

/// What GET /api/v1/todos/{id} answers beside `todo` (the list's hand-typed row, which clients read as their own row
/// type) from a manager that names todo_timeline (#10465): the paper's Conversation block, Results and Since you
/// looked (proposal 3.5 rows 3, 9 and 10), so the paper needs no second read. All four are absent from an older
/// manager, and when the manager could not read the to-do's history (the row still answers); recap and results also
/// when there is none.
public nonisolated struct TodoItemDetail: Codable, Hashable, Sendable {
    /// The rounds the paper shows, oldest first: the latest two that are not Background ones, the latest Background
